-- Top-level entity for the prototype module.
--
-- Generated by bust. A thin, fixed wrapper around the ipbus endpoint so the
-- module has one stable entity to instantiate. There is no user-editable region;
-- connect your logic to the to_hw/from_hw records.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

library ipbus;
use ipbus.ipbus.all;

use work.prototype_regfile_pkg.all;

entity prototype is
  generic (
    G_BASE_ADDRESS       : unsigned(31 downto 0) := 32x"0";
    G_CHECK_BASE_ADDRESS : boolean := true
  );
  port (
    clk     : in  std_logic;
    reset   : in  std_logic;
    ipb_in  : in  ipb_wbus;
    ipb_out : out ipb_rbus;
    to_hw    : out t_prototype_to_hw;
    from_hw  : in  t_prototype_from_hw
  );
end entity prototype;

architecture rtl of prototype is
begin

  i_endpoint : entity work.prototype_ipb_endpoint
    generic map (
      G_BASE_ADDRESS       => G_BASE_ADDRESS,
      G_CHECK_BASE_ADDRESS => G_CHECK_BASE_ADDRESS)
    port map (
      clk     => clk,
      reset   => reset,
      ipb_in  => ipb_in,
      ipb_out => ipb_out,
      to_hw    => to_hw,
      from_hw  => from_hw
    );

end architecture rtl;
